#!/usr/bin/env python3
"""Build a self-contained comparison and three print-ready direction books."""
from pathlib import Path
import base64
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).resolve().parent
books=[dict(id='kiln',n='01',title='Kiln',tag='An object worth keeping.',desc='Porcelain, architectural red and a dramatic shift in scale. The app feels like a small crafted object rather than a settings panel.',colors=['#F6EFE7','#C63A2E','#580F12','#D9C6B8','#2E2E2E'],names=['Porcelain','Vermilion','Oxblood','Clay','Graphite'],type='Expressive serif display; humanist system sans for controls; monospaced fingerprints.',typeclass='serif',principle='Use light and material as the flourish. A huge close crop opens into the complete Fold when the receipt is ready.',steps=[('Connect','A warm seam of light traces an incomplete form. A short status label stays stationary beside it.'),('Reveal','Pull back from the ceramic surface to the whole sculpture. Reveal the token number only after confirmation.'),('Handoff','Switch to a calm porcelain sheet with two matching numeric key fingerprints. Keep the sculpture out of the consent decision.')],motion='Gather → Form → Settle. A single 900–1200 ms reveal, then stillness. Button press: 100 ms depression, with no glow on the destructive/consent action.',avoid='Do not turn this into beige luxury packaging. Keep a large saturated red field, asymmetric crop and assertive typography. Avoid tiny, widely tracked body copy.',cost='Moderate. Pre-rendered artwork plus a masked reveal can establish the visual language before a live 3D renderer exists.'),dict(id='resonance',n='02',title='Resonance',tag='A network you can feel.',desc='Ink, mineral blue and quiet light. The Fold is the physical anchor inside a network that feels awake without becoming a dashboard.',colors=['#0B1220','#334155','#3882F6','#EDE8DF','#D64532'],names=['Midnight','Mineral','Signal blue','Porcelain','Vermilion'],type='Light geometric display; regular-weight system sans for labels; tabular figures only where needed.',typeclass='light',principle='Connection becomes an interference pattern. The light resolves when the real exchange is verified; it does not simulate nonexistent peers.',steps=[('Connect','Two wavefronts approach. Show the actual stage in text; the drawing is an abstract status metaphor, not network telemetry.'),('Reveal','A single light ring resolves around the sculpture. Surface the receipt and ownership without adding a wall of statistics.'),('Handoff','Two app identities face one another. Show both fingerprints explicitly; a calm central line confirms the approved transition.')],motion='Signal → Meet → Resolve. Slow, low-amplitude motion while an operation is pending; settle completely after confirmation. Pause decorative work when the window is hidden.',avoid='No star maps with invented peers, pulsing every control, fake distance readings or low-contrast gray-on-black captions. This is not a trading terminal.',cost='Highest. A shader or layered animation needs careful energy, contrast and reduced-motion handling. A static light study is the first implementation milestone.'),dict(id='assembly',n='03',title='Assembly',tag='Precise. Playful. Clearly yours.',desc='A strong graphic system: oversized type, porcelain forms, vermilion planes and a small cobalt signal. The making of the Fold becomes the visual story.',colors=['#FBF6F2','#E3422C','#2563EB','#0B0B0B','#D7D3CC'],names=['Ivory','Vermilion','Cobalt','Near black','Stone'],type='Bold condensed grotesk for the largest titles; readable system sans for instructions; system mono for precise data.',typeclass='bold',principle='Six ribbons become one sculpture. They represent the object’s geometry, never six verified peers or six people.',steps=[('Connect','Two simple circles align. Verification stages get a clear marker and a stable label; color never carries the state alone.'),('Reveal','The separated ribbons assemble into the Fold. A large token number and a restrained receipt label appear after confirmation.'),('Handoff','Graphic energy quiets down. Pair the two app windows, compare numeric fingerprints and present one explicit approval action.')],motion='Align → Fold → Belong. A decisive 650–900 ms assembly with a gentle finish. Short, tactile press feedback. Reduced motion uses a simple crossfade.',avoid='Do not carry poster-scale type into instructions or consent. Avoid extra Pause/Keep running decisions that complicate the accepted automatic journey.',cost='Lowest to moderate. Strong typography, vector geometry and a prepared sequence of object renders can carry the experience without a complex live scene.')]
css='''*{box-sizing:border-box}body{margin:0;background:#eeede8;color:#232720;font:16px/1.6 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:40px 30px 60px}a{color:#a13324;text-underline-offset:4px}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase;font-weight:700;color:#9b3926}h1{font:500 56px/1.1 Georgia,serif;letter-spacing:-2px;margin:15px 0}h2{font:500 40px/1.1 Georgia,serif;letter-spacing:-1px;margin:12px 0}h3{font-size:17px;margin:0 0 12px}p{margin:10px 0 20px}.intro{max-width:800px;font-size:19px}.quiet{font-size:13px;color:#686c60}.toc{display:flex;gap:12px;flex-wrap:wrap;margin:30px 0 40px}.toc a{background:#252920;color:#fff;text-decoration:none;border-radius:5px;padding:10px 18px}.book{margin:40px 0 75px;border-top:1px solid #cccfc2;padding-top:32px;scroll-margin-top:20px}.bookhead{display:flex;justify-content:space-between;align-items:end;gap:35px}.bookhead p{max-width:600px}.board{display:block;width:100%;border-radius:6px}.enlarge{display:block;border:0;background:transparent;padding:0;width:100%;cursor:zoom-in}.enlarge:focus-visible{outline:4px solid #315ed3;outline-offset:4px}.caption{display:flex;justify-content:space-between;gap:20px;font-size:12px;color:#636956;margin:10px 0 30px}.system{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:32px;padding:30px;background:#faf9f3;border:1px solid #d9dbd0;border-radius:8px}.swatches{display:flex;gap:10px;margin-bottom:25px}.swatch{flex:1;min-width:0}.swatch i{display:block;height:48px;border-radius:4px;border:1px solid #0001}.swatch span{display:block;font-size:10px;margin-top:5px}.specimen{font-size:62px;line-height:1.1;margin:12px 0}.serif{font-family:Georgia,serif}.light{font-weight:300;letter-spacing:-3px}.bold{font-weight:900;letter-spacing:-1px;font-family:Arial,sans-serif}.system p,.rules p{font-size:14px}.rules{display:grid;grid-template-columns:1fr 1fr 1fr;gap:30px;margin:30px 0}.rules>div{border-top:2px solid #9b3926;padding-top:18px}.recommend{background:#252920;color:#f4f3ea;padding:28px 32px;border-radius:8px;margin:35px 0}.recommend p{max-width:900px}.shared{border-top:1px solid #cccfc2;padding-top:28px;max-width:960px}.shared li{margin:10px 0}dialog{width:98vw;max-width:1800px;max-height:95vh;padding:14px;border:0;background:#f8f7f2;border-radius:8px}dialog::backdrop{background:#000b}dialog header{display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;background:#f8f7f2;padding:4px 6px 12px}.zoom-area{overflow:auto;max-height:80vh}.zoom-area img{width:1536px;max-width:none;display:block}.close{padding:8px 14px;font:inherit;border:1px solid #c3c7b8;background:white;border-radius:5px}.pdf-only{display:none}footer{font-size:12px;color:#686c60;margin-top:40px}@media(max-width:800px){main{padding:24px 16px 40px}h1{font-size:40px}h2{font-size:32px}.bookhead{display:block}.system,.rules{grid-template-columns:1fr;gap:22px}.system{padding:22px}.caption{display:block}.caption a{display:inline-block;margin-top:8px}.intro{font-size:17px}.recommend{padding:22px}.swatches{gap:6px}.swatch span{font-size:9px}}@page{size:A4 landscape;margin:12mm}@media print{body{background:white;font-size:12px}main{padding:0;max-width:none}.screen-only,dialog,body>nav{display:none!important}.pdf-only{display:block}.book{border:0;margin:0;padding:0}.bookhead{display:block}.bookhead p{max-width:900px}.board{width:100%;max-height:167mm;object-fit:contain}.print-page{break-after:page;height:184mm;overflow:hidden}.print-page:last-child{break-after:auto}.system{grid-template-columns:1fr 1fr 1fr;gap:20px;padding:20px}.rules{gap:20px}h1{font-size:40px}h2{font-size:30px}.system p,.rules p{font-size:12px}.caption{margin:8px 0}.specimen{font-size:52px}}
'''
def b64(p):return base64.b64encode(p.read_bytes()).decode()
def body(b,printing=False):
 board='<img class="board" src="data:image/png;base64,'+b64(HERE/(b['id']+'.png'))+'" alt="'+b['title']+' visual direction: hero app screen, three journey studies, palette, type and motion frames">'
 head=f'<div class="bookhead"><div><div class="eyebrow">Direction {b["n"]}</div><h2>{b["title"]}</h2><p><strong>{b["tag"]}</strong></p></div><p>{b["desc"]}</p></div>'
 sw=''.join(f'<div class="swatch"><i style="background:{c}"></i><span>{n}<br>{c}</span></div>' for c,n in zip(b['colors'],b['names']))
 sys=f'<div class="system"><div><h3>Palette & type</h3><div class="swatches">{sw}</div><div class="specimen {b["typeclass"]}">Aa / 002</div><p>{b["type"]}</p></div><div><h3>Visual principle</h3><p>{b["principle"]}</p><h3>Motion</h3><p>{b["motion"]}</p></div><div><h3>Keep it disciplined</h3><p>{b["avoid"]}</p><h3>Build effort</h3><p>{b["cost"]}</p></div></div>'
 rules='<div class="rules">'+''.join(f'<div><h3>{i+1:02} / {name}</h3><p>{text}</p></div>' for i,(name,text) in enumerate(b['steps']))+'</div>'
 if printing:
  return '<section class="print-page"><div class="eyebrow">ATTESTNODE / '+b['title'].upper()+' / CONCEPT STUDY</div>'+board+'<p class="quiet">AI-generated visual direction, not implemented software. Typography and microcopy in artwork are exploratory.</p></section><section class="print-page">'+head+sys+'</section><section class="print-page"><div class="eyebrow">THE ACCEPTED JOURNEY / '+b['title'].upper()+'</div><h2>Same steps. Stronger character.</h2>'+rules+shared+'</section>'
 return f'<section class="book" id="{b["id"]}">'+head+'<button class="enlarge" aria-label="Enlarge '+b['title']+' design board">'+board+'</button><div class="caption"><span>Generated concept art · click to inspect at full resolution</span><a href="https://github.com/amiller/apple-attest-p2p/raw/refs/heads/main/design/visual-books/'+b['id']+'.pdf">Download '+b['title']+' book · PDF</a></div>'+sys+rules+'</section>'
shared='''<div class="shared"><h3>Rules shared by all three directions</h3><ul><li>The accepted journey stays intact. Launch automatically connects; there is no new “Keep running” gate or second claim introduced by a concept button.</li><li>Use “Verifying this app”, “Connecting to a peer”, “Receipt confirmed” and “Preparing your Fold” for distinct real states. A rendering delay is not a network failure.</li><li>The consent screen always compares numeric key fingerprints and explains the account-control change. The user signs their own copy; they do not transfer their NFT to another developer.</li><li>Never imply verified human identity, invent peer counts, or use the Fold’s six ribbons as a peer count. Artwork captions remain exploratory; these rules govern implementation.</li><li>Body and control text must stay readable at normal size. Keep status visible in words as well as color. Honor Reduce Motion; idle scenes should settle and stop consuming resources.</li><li>Start with a static native screen, then add a bounded reveal. Reuse the real procedural Fold renderer; these new concept shapes are not replacement minted NFT images.</li></ul></div>'''
intro='''<header class="screen-only"><div class="eyebrow">ATTESTNODE / THREE VISUAL DESIGN BOOKS</div><h1>Give the journey a character.</h1><p class="intro">Three distinct directions for the same accepted flow. Each includes a concept board, visual rules, palette, typography, motion, and the connection → reveal → handoff treatment.</p><p class="quiet">Built-in image generation produced the concept boards. These are art-direction studies, not screenshots of implemented software or exact new NFT renders.</p><nav class="toc"><a href="#kiln">01 / Kiln</a><a href="#resonance">02 / Resonance</a><a href="#assembly">03 / Assembly</a></nav></header>'''
recommend='''<div class="recommend screen-only"><div class="eyebrow" style="color:#f09d77">MY PICK / ASSEMBLY</div><h2>Start with Assembly.<br>Give it Kiln’s material quality.</h2><p>Assembly gives the app a recognizable face and makes progress easy to understand. Keep its bold type and clear geometry, render the Fold with Kiln’s tactile lighting, and keep consent restrained. Resonance is the more atmospheric alternative, with a higher animation and energy budget.</p></div>'''
script='''<dialog id="zoom"><header><span id="zoom-title">Design board</span><button class="close">Close ×</button></header><div class="zoom-area"><img id="zoom-image" alt="Enlarged design board"></div></dialog><script>const d=document.getElementById('zoom');document.querySelectorAll('.enlarge').forEach(b=>b.addEventListener('click',()=>{const i=b.querySelector('img');document.getElementById('zoom-image').src=i.src;document.getElementById('zoom-image').alt=i.alt;document.getElementById('zoom-title').textContent=b.getAttribute('aria-label');d.showModal()}));d.querySelector('.close').addEventListener('click',()=>d.close());</script>'''
footer='''<footer>Concept boards and exact generation/edit prompts: <a href="https://github.com/amiller/apple-attest-p2p/tree/main/design/visual-books">source folder</a>. The journey itself is unchanged. Images and text are embedded for offline use; PDF/source links need internet access. Anyone with this unlisted report link can view it.</footer>'''
def page(content):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AttestNode — visual design books</title><style>'+css+'</style></head><body><main>'+content+'</main></body></html>'
out=ROOT/'build/visual-books';out.mkdir(parents=True,exist_ok=True)
(out/'index.html').write_text(page(intro+recommend+''.join(body(b) for b in books)+shared+footer+script))
for b in books:(out/(b['id']+'.html')).write_text(page(body(b,True)))
print(out/'index.html')
